fn code_editor() -> impl View {
    let code = State::new(
        "fn total(prices: &[f64]) -> f64 {\n    // Sum of every price\n    prices.iter().sum()\n}\n"
            .to_owned(),
    );
    CodeEditor::new(code.binding())
        .diagnostics(vec![
            CodeDiagnostic::warning(3, 5, 6, "`prices` could be empty").hint("Return 0.0 first"),
        ])
        .rows(10)
}

